// Projects array
const PROJECTS = [
    { title: "Amethyst", type: "art", date: "2025-01" },
    { title: "Mochi Donuts", type: "website", date: "2026-04" },
    { title: "Game One", type: "game", date: "2026-10" }
]

// Sectors of the different types of work
const SECTORS = {
    art: [0, 1/3],
    web: [1/3, 2,3],
    game: [2/3, 1]
}

/* Code generated by Claude for converting date / sector into polar values */

const MS_PER_YEAR = 365.25 * 24 * 60 * 60 * 1000;
const MAX_AGE = 3; // Oldest project year at outer ring
const R_MIN = 0.1; // To make sure no plot is at r = 0 (center)
const PAD = 0.02; // Keeping padding at sector edges

const list = document.querySelector(".orrery-plots");
const now = new Date();
let i = 0;

for (const [type, items] of Object.entries(Object.groupBy(PROJECTS, p => p.type))) {
    const [start, end] = SECTORS[type];
    const span = end - start - 2 * PAD; // Usable sector width

    // Sort by the date
    items.sort((a, b) => new Date(a.date) - new Date(b.date));

    items.forEach((PROJECTS, k) => {
        const turn = start + PAD + (k + 0.5) * (span / items.length);

        // Distance: age mapped onto 0–1 of the radius
        const age = (now - new Date(project.date)) / MS_PER_YEAR;
        const t = Math.min(age / MAX_AGE, 1);
        const r = R_MIN + t * (1 - R_MIN);

        const li = document.createElement("li");
        li.className = "orrery-plot";
        li.style.setProperty("--turn", turn.toFixed(4));
        li.style.setProperty("--distance", `${(r * 50).toFixed(2)}%`);  // 50% = outer ring
        li.style.setProperty("--i", i++);

        const a = document.createElement("a");
        a.href = project.url;
        a.textContent = project.title;  // accessible name; hide visually if you only want a dot
        li.append(a);

        list.append(li);


    });
}